package net.zartra.gui;
import org.bukkit.Color;import org.bukkit.inventory.meta.ItemMeta;import java.lang.reflect.*;
final class CompatItemMeta {private CompatItemMeta(){}static void apply(ItemMeta meta,MenuItem item){if(meta==null)return;try{if(item.unbreakable)meta.getClass().getMethod("setUnbreakable",boolean.class).invoke(meta,true);}catch(Exception ignored){}try{if(item.customModelData>=0)meta.getClass().getMethod("setCustomModelData",int.class).invoke(meta,item.customModelData);}catch(Exception ignored){}try{if(item.headOwner!=null&&!item.headOwner.isEmpty())meta.getClass().getMethod("setOwner",String.class).invoke(meta,item.headOwner);}catch(Exception ignored){}try{if(item.leatherColor!=null&&!item.leatherColor.isEmpty()){String[] c=item.leatherColor.split(",");meta.getClass().getMethod("setColor",Color.class).invoke(meta,Color.fromRGB(Integer.parseInt(c[0]),Integer.parseInt(c[1]),Integer.parseInt(c[2])));}}catch(Exception ignored){}}}